package enyo.linux.buildtools;

import java.io.IOException;
import java.io.PrintWriter;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

class Updater {
    private Updater() {}

    /**
     * Replace auto-generated file segments.
     */
    static void patchSegments(String file,
        Map<String, List<String>> replacements) throws IOException {
        String segmentPrefix = autoGenerated + "  (";

        Path path = Path.of(file);
        List<String> lines = Files.readAllLines(path);
        var newLines = new ArrayList<String>();
        var remaining = new HashSet<>(replacements.keySet());
        for (int lineno = 0; lineno < lines.size(); ++lineno) {
            String line = lines.get(lineno);
            int indentOffset = line.indexOf(segmentPrefix);
            if (indentOffset < 0) {
                // Not in an auto-generated region.
                newLines.add(line);
                continue;
            }

            // Extract the segment name.
            if (!line.endsWith(")"))
                throw new IOException(String.format(
                    "Malformed line in %s: %s", file, line));
            String segmentName = line.substring(
                indentOffset + segmentPrefix.length(),
                line.length() - 1);
            List<String> replacement = replacements.get(segmentName);
            if (replacement == null)
                throw new IOException(String.format(
                        "Unknown segment in %s: %s", file, segmentName));
            newLines.add(line);
            remaining.remove(segmentName);

            // Patch in the replacement lines, using the indentation.
            String indent = line.substring(0, indentOffset);
            for (String newLine : replacement)
                newLines.add(indent + newLine);

            // Search for the end marker.
            {
                String end =
                    "// End auto-generated section.  (" + segmentName + ')';
                for (; lineno < lines.size(); ++lineno) {
                    line = lines.get(lineno);
                    if (line.endsWith(end))
                        break;
                }
                if (lineno == lines.size())
                    throw new IOException(String.format(
                        "Missing segment end marker in %s: %s",
                        file, segmentName));
                newLines.add(indent + end);
            }
        }

        if (!remaining.isEmpty())
            throw new IOException(String.format(
                    "Missing patch segments in %s: %s",
                    file, remaining));

        Files.write(path, newLines);
    }

    static void writeMacroClass(String className,
        Map<Architecture, Map<String, Long>> values,
        Predicate<String> filter) throws IOException {
        var commonMacros = new HashSet<String>();
        {
            boolean first = true;
            for (var macros : values.values()) {
                if (first) {
                    first = false;
                    commonMacros.addAll(macros.keySet());
                } else
                    commonMacros.retainAll(macros.keySet());
            }
        }
        commonMacros.removeIf(filter.negate());

        var commonValues = new HashMap<String, Long>();
        MACRO: for (String macro : commonMacros) {
            Long value = null;
            for (var macros : values.values()) {
                Long newValue = macros.get(macro);
                newValue.longValue();
                if (value == null)
                    value = newValue;
                else if (value.longValue() != newValue.longValue())
                    continue MACRO;
            }
            commonValues.put(macro, value);
        }

        var outPath = Path.of(String.format(
                "src/enyo.linux/enyo/linux/%s.java", className));
        try (var out = new PrintWriter(Files.newBufferedWriter(outPath))) {
            out.format("""
%s
package enyo.linux;

class %s {
""",
                autoGenerated, className);

            // Field definitions.
            commonMacros.stream()
                .sorted()
                .forEach(name -> out.format("""
    public final static int %s;
""",
                    name));

            out.write("""

    static {
        String osArch = System.getProperty("os.arch");

""");

            // Architecture-indepented field initialization.  These
            // need to be separate assignments to inhibit constant
            // propagation in the Java compiler (in case of future
            // architectural divergence).
            commonValues.entrySet().stream()
                .sorted(Comparator.comparing(Map.Entry::getKey))
                .forEach(e -> out.format("""
        %s = %d;
""",
                    e.getKey(), (int) (long) e.getValue()));

            // Architecture-specific field initialization.
            out.print("\n        ");
            values.entrySet().stream()
                .sorted(Comparator.comparing(Map.Entry::getKey))
                .forEach(archMacros -> {
                Architecture arch = archMacros.getKey();
                out.format("if (osArch.equals(\"%s\")) {%n",
                    arch.name().toLowerCase());
                archMacros.getValue().entrySet().stream()
                    .filter(e -> commonMacros.contains(e.getKey()))
                    .filter(e -> !commonValues.containsKey(e.getKey()))
                    .sorted(Comparator.comparing(Map.Entry::getKey))
                    .forEach(e -> out.format("""
            %s = %d;
""",
                        e.getKey(), (int) (long) e.getValue()));

                out.write("""
        } else \
""");
            });

            out.write("""
{
            throw new UnsupportedOperationException(osArch);
        }
    }
}
""");
        }
    }

    private final static String autoGenerated =
        "// Auto-generated.  Do not edit.";
}
